CURRENT RECORD:
{{ JSON.stringify({ company_name: $json.company_name, state: $json.state, website: $json.website, data_mode: $json.data_mode, practice_areas: $json.practice_areas, offices: $json.offices, leadership: $json.leadership, year_founded: $json.year_founded, attorney_count: $json.attorney_count, missing_information: $json.missing_information, classification_reason: $json.reason }) }}

EVIDENCE ALREADY COLLECTED (website text):
{{ $json.website_text || "(none)" }}

