const bases = $('High or Moderate Fit?').all(0);
const now = new Date().toISOString();
function mergeOne(base, row) {
const e = row.output;
const rec = Object.assign({}, base);
if (!e || typeof e !== 'object') {
  rec.enrichment = null;
  rec.enrichment_status = 'failed';
  rec.missing_information = (base.missing_information || []).concat(['Research agent failed - rerun enrichment']);
  return { json: rec };
}
const isLive = base.data_mode === 'LIVE';
const prov = (base.provenance || []).slice();
(e.evidence_backed_signals || []).forEach(function (s) {
  prov.push({ field: 'signal:' + s.type, value: s.signal, source: 'Research Agent', url: s.source_url || '', evidence_quote: s.evidence_quote || '',
              status: isLive ? ((s.source_url && s.evidence_quote) ? 'verified' : 'estimated') : 'sample_demo', extracted_at: now });
});
function known(v) { return v && String(v).toLowerCase() !== 'unknown'; }
rec.provenance = prov;
rec.enrichment = e;
rec.enrichment_status = 'completed';
if (e.office_locations && e.office_locations.length) rec.offices = Array.from(new Set((rec.offices || []).concat(e.office_locations)));
if (e.leadership && e.leadership.length) rec.leadership = Array.from(new Set((rec.leadership || []).concat(e.leadership)));
if (!rec.revenue && known(e.size_and_revenue_notes) && e.revenue_status !== 'unknown') {
  rec.revenue = e.size_and_revenue_notes;
  rec.revenue_status = isLive ? e.revenue_status : 'sample_demo';
}
rec.ai_source_urls = Array.from(new Set((rec.ai_source_urls || []).concat(e.sources_consulted || [])));
return { json: rec };
}
return $input.all().map(function (it, idx) { return mergeOne(bases[idx].json, it.json); });

const cfg = $('Run Configuration').first().json;
const W = cfg.weights, T = cfg.thresholds;
const r = $json;
const ent = r.enrichment || {};
const comps = [];
function round1(x) { return Math.round(x * 10) / 10; }
function add(key, label, max, pts, note) { comps.push({ key: key, label: label, max: max, points: pts === null ? null : round1(pts), scored: pts !== null, note: note }); }

// 1. Insurance-defense practice fit (AI, evidence-grounded)
const idf = r.insurance_defense_fit;
const aiF = idf === 'Strong' ? 1 : idf === 'Partial' ? 0.5 : idf === 'None' ? 0 : null;
const SB = cfg.scorecard_bands || { strong: 15, moderate: 5 };
const sc = r.insurance_score;
const scF = (sc === null || sc === undefined) ? null : sc >= SB.strong ? 1 : sc >= SB.moderate ? 0.6 : sc >= 0 ? 0.2 : 0;
const insF = aiF === null ? scF : scF === null ? aiF : (aiF + scF) / 2;
add('insurance_defense', 'Insurance-defense practice fit', W.insurance_defense, insF === null ? null : W.insurance_defense * insF,
  'AI assessment: ' + idf + '; keyword scorecard: ' + (sc === null || sc === undefined ? 'n/a' : sc + ' (' + r.insurance_band + ')'));
// 2. Geography
const geo = (r.state === 'FL' || r.state === 'GA');
add('geography', 'Florida/Georgia geographic fit', W.geography, geo ? W.geography : 0, 'State: ' + r.state);
// 3. B2B focus
const b = r.b2b_focus;
add('b2b', 'B2B client focus', W.b2b, b === 'Primarily B2B/Insurers' ? W.b2b : b === 'Mixed' ? W.b2b * 0.5 : b === 'Primarily Consumer' ? 0 : null, 'AI assessment: ' + b);
// 4. Size (attorney count; revenue is not required)
const att = r.attorney_count;
let szf = null;
const SZ = cfg.size_band_attorneys || { min: 10, max: 400 };
if (att !== null && att !== undefined) szf = (att >= SZ.min && att <= SZ.max) ? 1 : (att >= 5 && att < SZ.min) ? 0.5 : att > SZ.max ? 0.4 : 0.2;
