const score = matched.reduce(function (s, t) { return s + t.weight; }, 0);
const hasText = !!(r.website_text && r.website_text.length > 200);
const band = !hasText ? 'No website text' : score >= bands.strong ? 'Strong insurance focus' : score >= bands.moderate ? 'Moderate insurance focus' : score >= 0 ? 'Weak / unclear' : 'Likely non-insurance or plaintiff';
r.insurance_score = hasText ? score : null;
r.insurance_band = band;
r.insurance_terms_matched = matched.sort(function (a, b) { return b.weight - a.weight; }).map(function (t) { return t.term + ' (' + (t.weight > 0 ? '+' : '') + t.weight + ')'; });
r.plaintiff_terms = matched.filter(function (t) { return t.weight === -5; }).map(function (t) { return t.term; });

const risks = (r.potential_risks || []).slice();
if (hasText) {
  if (r.insurance_defense_fit === 'Strong' && score < bands.moderate) risks.push('Keyword scorecard (' + score + ') does not corroborate the AI "Strong" insurance-defense rating - verify practice mix');
  if ((r.insurance_defense_fit === 'None' || r.insurance_defense_fit === 'Unknown') && score >= bands.strong) risks.push('Keyword scorecard (' + score + ') suggests insurance focus but AI rated fit ' + r.insurance_defense_fit + ' - verify');
  if (r.plaintiff_terms.length) risks.push('Plaintiff-side language on website: ' + r.plaintiff_terms.join(', '));
}
if (r.defense_vs_plaintiff === 'Plaintiff') risks.push('AI assessment: primarily plaintiff-side');
if (r.civil_vs_criminal === 'Criminal') risks.push('AI assessment: primarily criminal practice');
r.potential_risks = risks;

const att = r.attorney_count;
const prov = (r.provenance || []).slice();
const now = new Date().toISOString();
if (att !== null && att !== undefined && att > 0) {
  const lo = att * rpa.low, hi = att * rpa.high;
  const fmt = function (n) { return '$' + (n / 1e6).toFixed(1) + 'M'; };
  r.revenue_estimate_low = lo; r.revenue_estimate_high = hi;
  r.revenue_estimate = fmt(lo) + '-' + fmt(hi) + ' (est.)';
  r.in_size_band = att >= 10 && att <= 400;
  if (!r.revenue) {
    r.revenue = r.revenue_estimate; r.revenue_status = r.data_mode === 'LIVE' ? 'estimated' : 'sample_demo';
    prov.push({ field: 'revenue', value: r.revenue_estimate, source: 'Formula: attorney_count x $300k-$500k (sponsor rule of thumb)', url: '', evidence_quote: att + ' attorneys', status: 'estimated', extracted_at: now });
  }
} else { r.revenue_estimate = null; r.in_size_band = null; }
if (hasText) prov.push({ field: 'insurance_score', value: String(score), source: 'Sponsor keyword scorecard v2.3', url: r.website || '', evidence_quote: r.insurance_terms_matched.join('; ').slice(0, 480), status: 'estimated', extracted_at: now });
r.provenance = prov;

// Names used by the public-record lookups that follow
const base = String(r.company_name || '').replace(/^(the )?law offices? of /i, '').replace(/,?\s+(llp|l\.l\.p\.|llc|l\.l\.c\.|pllc|p\.l\.l\.c\.|p\.a\.|pa|p\.c\.|pc|p\.l\.|pl|chartered|attorneys at law|attorneys|lawyers)\.?$/i, '').replace(/,\s*$/, '').trim();
r.registry_name = base;
r.sunbiz_search_url = 'https://search.sunbiz.org/Inquiry/CorporationSearch/SearchResults?inquiryType=EntityName&searchTerm=' + encodeURIComponent(base.toUpperCase());
r.ga_sos_search_url = 'https://ecorp.sos.ga.gov/BusinessSearch';
return { json: r };

// Merge Sunbiz Daily (Florida entity filings) and USAspending (federal contract awards) back onto each firm.
// Not finding a firm in either source is NOT treated as negative.
const bases = $('Insurance Scorecard + Revenue Estimate').all();
const sun = $('Sunbiz Entity Lookup').all();
const usa = $input.all();
const now = new Date().toISOString();
const SUFFIX = /\b(llp|llc|pllc|pa|pc|pl|chartered|inc|corp|corporation|law firm|law group|law offices?|attorneys at law|of)\b/g;
function core(n) { return String(n || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ').replace(SUFFIX, ' ').replace(/ +/g, ' ').trim(); }
return bases.map(function (b, i) {
  const r = Object.assign({}, b.json);
  const prov = (r.provenance || []).slice();
  const target = core(r.registry_name || r.company_name);
  // --- Sunbiz Daily
  const sd = (sun[i] && sun[i].json) || {};
  const filings = Array.isArray(sd.filings) ? sd.filings : [];
  const hit = filings.find(function (f) { const c = core(f.corporation_name); return c === target || (target.length > 6 && (c.indexOf(target) === 0 || target.indexOf(c) === 0)); });
  if (hit) {
    r.entity_name = hit.corporation_name; r.entity_number = hit.corporation_number; r.entity_type = hit.filing_type_display;
    r.entity_status = hit.status === 'A' ? 'Active' : hit.status === 'I' ? 'Inactive' : (hit.status || 'Unknown');
    r.entity_file_date = hit.file_date || null; r.entity_status_label = 'Verified';
    r.entity_source_url = 'https://search.sunbiz.org/Inquiry/CorporationSearch/SearchResults?inquiryType=DocumentNumber&searchTerm=' + encodeURIComponent(hit.corporation_number || '');
    prov.push({ field: 'entity_status', value: r.entity_status + ' - ' + hit.corporation_name + ' (' + hit.corporation_number + ', filed ' + hit.file_date + ')', source: 'Sunbiz Daily API (Florida Division of Corporations data)', url: r.entity_source_url, evidence_quote: '', status: 'verified', extracted_at: now });
    if (!r.year_founded && hit.file_date) {
      const y = parseInt(String(hit.file_date).slice(0, 4), 10);
      r.year_founded = y; r.years_in_operation = new Date().getFullYear() - y; r.year_founded_status = 'estimated';
      prov.push({ field: 'year_founded', value: String(y), source: 'Sunbiz filing date (entity may post-date firm founding)', url: r.entity_source_url, evidence_quote: '', status: 'estimated', extracted_at: now });
    }
  } else {
    r.entity_status = null; r.entity_status_label = sd.error ? 'Lookup failed' : 'Missing';
    r.entity_source_url = r.state === 'FL' ? r.sunbiz_search_url : r.ga_sos_search_url;
    r.missing_information = (r.missing_information || []).concat(['Entity registration (check ' + (r.state === 'FL' ? 'Sunbiz' : 'GA Secretary of State') + ' manually)']);
  }
  // --- USAspending
  const ud = (usa[i] && usa[i].json) || {};
  const awards = (Array.isArray(ud.results) ? ud.results : []).filter(function (a) { const c = core(a['Recipient Name']); return c === target || (target.length > 6 && c.indexOf(target) === 0); });
  r.federal_awards_count = awards.length;
  r.federal_awards_total = Math.round(awards.reduce(function (s, a) { return s + (Number(a['Award Amount']) || 0); }, 0));
  r.federal_award_agencies = Array.from(new Set(awards.map(function (a) { return a['Awarding Agency']; }))).slice(0, 5);
  if (awards.length) {
    const rid = awards[0].recipient_id;
    r.federal_awards_url = rid ? 'https://www.usaspending.gov/recipient/' + rid + '/latest' : 'https://www.usaspending.gov/search';
    prov.push({ field: 'federal_awards', value: awards.length + ' contract award(s), $' + r.federal_awards_total.toLocaleString('en-US') + ' (' + r.federal_award_agencies.join(', ') + ')', source: 'USAspending.gov API', url: r.federal_awards_url, evidence_quote: '', status: 'verified', extracted_at: now });
  }
  r.provenance = prov;
  return { json: r };
});

// Fallback: if Apify could not scrape a firm's site (busy / blocked), use the homepage fetched directly by n8n.
const cands = $('Extract Website Text').all().map(function (i) { return i.json; });
const now = new Date().toISOString();
const NL = String.fromCharCode(10), CR = String.fromCharCode(13), TAB = String.fromCharCode(9);
return $input.all().map(function (item, idx) {
  const c = Object.assign({}, cands[idx] || {});
  if (c.pages_scraped > 0 || !c.website) return { json: c };
  const html = (item.json && typeof item.json.data === 'string') ? item.json.data : '';
  let text = html.replace(/<script[^>]*>[^]*?<[/]script>/gi, ' ').replace(/<style[^>]*>[^]*?<[/]style>/gi, ' ').replace(/<[^>]*>/g, ' ');
  text = text.split(NL).join(' ').split(CR).join(' ').split(TAB).join(' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/ +/g, ' ').trim().slice(0, 8000);
  if (text.length > 200) {
    c.website_text = '=== PAGE: ' + c.website + ' (homepage, direct fetch) ===' + NL + text;
    c.pages_scraped = 1; c.scraped_page_urls = [c.website]; c.scrape_method = 'direct_fetch_fallback'; delete c.scrape_note;
    c.sources = (c.sources || []).concat([{ field: 'website_page', value: '(homepage text, direct fetch fallback)', source: 'Firm website (direct fetch)', url: c.website, status: 'verified', extracted_at: now }]);
    c.source_urls = Array.from(new Set((c.source_urls || []).concat([c.website])));
  }
  return { json: c };
});
